class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def helper(num):
            n = len(num)

            def dp(pos, tight, has_first, even_num, cur_num):
                if pos == n:
                    # Check if even count equals odd count and number is divisible by k
                    return 1 if even_num == 0 and cur_num == 0 else 0

                res = 0
                bound = num[pos] if tight else 9

                for i in range(bound + 1):
                    new_tight = tight and (i == bound)
                    new_has_first = has_first or (i > 0)

                    if not has_first and i == 0:
                        new_has_first = True

                    new_even_num = even_num
                    if i % 2 == 0:
                        new_even_num += 1
                    else:
                        new_even_num -= 1

                    result = dp(pos + 1, new_tight, new_has_first, new_even_num, (cur_num * 10 + i) % k)
                    res += result

                return res

            return dp(0, True, False, 0, 0)

        # Convert numbers to tuples of digits
        num_high = tuple(map(int, str(high)))
        num_low = tuple(map(int, str(low - 1)))

        # Count beautiful integers in [0, high] minus [0, low-1]
        result_high = helper(num_high)
        result_low = helper(num_low)

        return result_high - result_low

